import { createServer } from 'node:http';
import { readFile, mkdir, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = process.env.DATA_FILE || join(ROOT, 'data', 'books.json');
const CSS_FILE = join(ROOT, 'public', 'styles.css');
const MAX_BODY = 64 * 1024;
let pendingWrite = Promise.resolve();

const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[char]);

async function loadBooks() {
  try {
    const books = JSON.parse(await readFile(DATA_FILE, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

// Serialize mutations and atomically replace the file so concurrent submissions cannot lose books.
function updateBooks(change) {
  const operation = pendingWrite.then(async () => {
    const books = await loadBooks();
    const result = change(books);
    if (result === false) return false;
    await mkdir(dirname(DATA_FILE), { recursive: true });
    const temporary = `${DATA_FILE}.${randomUUID()}.tmp`;
    await writeFile(temporary, JSON.stringify(books, null, 2) + '\n', 'utf8');
    await rename(temporary, DATA_FILE);
    return result;
  });
  pendingWrite = operation.catch(() => {});
  return operation;
}

function send(res, status, content, type = 'text/html; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(content);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function icon(name, size = 20) {
  const paths = {
    book: '<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21V5.5Z"/><path d="M4 18.5A2.5 2.5 0 0 1 6.5 16H20"/>',
    plus: '<path d="M12 5v14M5 12h14"/>',
    arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>',
    back: '<path d="M19 12H5m6 6-6-6 6-6"/>',
    check: '<path d="m5 12 4 4L19 6"/>',
    link: '<path d="M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7.1-7.1l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7.1 7.1l1.7-1.7"/>',
  };
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;
}

function layout({ title, active = 'library', content }) {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f8f7f3"><title>${escapeHtml(title)} · Marginalia</title><link rel="stylesheet" href="/styles.css"></head>
<body><div class="app-shell">
<aside class="sidebar"><a href="/" class="brand" aria-label="Marginalia home"><span class="brand-mark">${icon('book', 22)}</span><span>marginalia<span class="brand-dot">.</span></span></a>
<div class="sidebar-content"><div class="nav-label">YOUR SPACE</div><nav aria-label="Main navigation"><a class="nav-item ${active === 'library' ? 'active' : ''}" href="/">${icon('book', 19)}<span>My library</span></a><a class="nav-item ${active === 'add' ? 'active' : ''}" href="/books/new">${icon('plus', 19)}<span>Add a book</span></a></nav></div>
<div class="sidebar-footer"><span class="footer-icon">✳</span><span>A little home for the<br>stories that stay with you.</span></div></aside>
<div class="main-area"><header class="topbar"><span>YOUR PERSONAL BOOKSHELF</span><span class="topbar-right"><span class="topbar-dot"></span> Happy reading</span></header><main class="content">${content}</main><footer class="mobile-footer">Marginalia <span>✳</span> A home for your reading life</footer></div></div></body></html>`;
}

function bookCard(book, index) {
  const done = book.status === 'finished';
  const href = `/books/${encodeURIComponent(book.id)}`;
  return `<a class="book-card" href="${href}"><span class="book-cover cover-${index % 5}" aria-hidden="true"><span class="cover-lines"><i></i><i></i><i></i></span><span class="cover-symbol">✳</span></span><span class="book-card-info"><span class="book-title">${escapeHtml(book.title)}</span><span class="book-author">by ${escapeHtml(book.author)}</span><span class="book-meta">${done ? 'Finished' : 'Currently reading'} <span class="meta-separator">·</span> ${book.notes ? 'Notes added' : 'No notes yet'}</span></span><span class="card-arrow">${icon('arrow', 19)}</span></a>`;
}

function home(books) {
  const reading = books.filter((book) => book.status !== 'finished');
  const finished = books.filter((book) => book.status === 'finished');
  const shelf = (items, emptyText, offset = 0) => items.length
    ? `<div class="book-grid">${items.map((book, index) => bookCard(book, index + offset)).join('')}</div>`
    : `<div class="empty-section"><span class="empty-spark">✳</span><p>${emptyText}</p></div>`;
  return layout({ title: 'My library', content: `
<div class="page-intro"><div><div class="eyebrow"><span class="eyebrow-line"></span> A SPACE FOR YOUR STORIES</div><h1>Your reading life,<br><em>all in one place.</em></h1><p>Keep the books you’re reading close, and the ones you’ve loved even closer.</p></div><a class="button primary intro-button" href="/books/new">${icon('plus', 18)} Add a book</a></div>
<div class="stats"><div class="stat"><span class="stat-number">${reading.length.toString().padStart(2, '0')}</span><span class="stat-label">CURRENTLY READING</span></div><div class="stat"><span class="stat-number">${finished.length.toString().padStart(2, '0')}</span><span class="stat-label">BOOKS FINISHED</span></div><div class="stat stat-quote"><span class="quote-mark">“</span><span>There is no friend as loyal as a book.<small>— ERNEST HEMINGWAY</small></span></div></div>
<section class="shelf-section"><div class="section-heading"><div><span class="section-kicker">ON YOUR NIGHTSTAND</span><h2>Currently reading <span class="count">${reading.length}</span></h2></div><span class="section-decoration">01 / 02</span></div>${shelf(reading, 'Your next great read starts here. Add a book to begin.')}</section>
<section class="shelf-section finished-section"><div class="section-heading"><div><span class="section-kicker">THE STORIES YOU’VE KEPT</span><h2>Finished books <span class="count">${finished.length}</span></h2></div><span class="section-decoration">02 / 02</span></div>${shelf(finished, 'Books you finish will find a home here.', reading.length)}</section>
` });
}

function formPage(values = {}, error = '') {
  return layout({ title: 'Add a book', active: 'add', content: `
<div class="form-page"><a class="back-link" href="/">${icon('back', 17)} Back to library</a><div class="eyebrow"><span class="eyebrow-line"></span> A NEW CHAPTER</div><h1>Add a <em>book.</em></h1><p class="form-intro">Every good story deserves a place on your shelf. Tell us what you’re reading.</p>
<form class="book-form" action="/books" method="post"><div class="form-heading"><span class="form-heading-icon">✳</span><div><h2>Book details</h2><p>The little things worth remembering.</p></div></div>
${error ? `<p class="form-error" role="alert">${escapeHtml(error)}</p>` : ''}
<div class="field"><label for="title">Book title <span>*</span></label><input id="title" name="title" type="text" maxlength="200" required placeholder="e.g. The Midnight Library" value="${escapeHtml(values.title || '')}"></div>
<div class="field"><label for="author">Author <span>*</span></label><input id="author" name="author" type="text" maxlength="200" required placeholder="e.g. Matt Haig" value="${escapeHtml(values.author || '')}"></div>
<div class="field"><label for="notes">Your notes <span class="optional">OPTIONAL</span></label><textarea id="notes" name="notes" maxlength="10000" rows="6" placeholder="What made you pick it up? Favorite lines, passing thoughts, anything at all...">${escapeHtml(values.notes || '')}</textarea><small>A place for your thoughts as you read. You can leave this blank.</small></div>
<div class="form-actions"><a class="button secondary" href="/">Cancel</a><button class="button primary" type="submit">Add to my library ${icon('arrow', 18)}</button></div></form><p class="form-footnote">✳ &nbsp; You can mark this book as finished when you’re done reading.</p></div>` });
}

function detail(book) {
  const done = book.status === 'finished';
  return layout({ title: book.title, content: `
<div class="detail-page"><a class="back-link" href="/">${icon('back', 17)} Back to library</a><div class="detail-hero"><div class="detail-cover" aria-hidden="true"><div class="detail-cover-top">MARGINALIA · LIBRARY</div><span class="detail-cover-symbol">✳</span><div class="detail-cover-bottom">A STORY WORTH KEEPING</div></div><div class="detail-heading"><div class="eyebrow"><span class="eyebrow-line"></span> YOUR BOOKSHELF</div><span class="status-pill ${done ? 'status-done' : ''}"><span></span>${done ? 'Finished' : 'Currently reading'}</span><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by <strong>${escapeHtml(book.author)}</strong></p><div class="detail-actions">${!done ? `<form action="/books/${encodeURIComponent(book.id)}/finish" method="post"><button class="button primary" type="submit">${icon('check', 18)} Mark as finished</button></form>` : `<span class="finished-message">${icon('check', 18)} A story completed</span>`}<button class="button secondary share-button" type="button" onclick="navigator.clipboard.writeText(location.href).then(() => { this.querySelector('span').textContent = 'Link copied!'; }).catch(() => { this.querySelector('span').textContent = 'Copy from address bar'; })">${icon('link', 17)} <span>Copy link</span></button></div><p class="share-hint">This page has its own link — share it with anyone.</p></div></div>
<section class="notes-section"><div class="section-heading"><div><span class="section-kicker">IN THE MARGINS</span><h2>My notes</h2></div><span class="section-decoration">✳</span></div><div class="notes-paper">${book.notes ? `<p class="notes-content">${escapeHtml(book.notes)}</p>` : `<p class="no-notes">No notes for this book yet. Sometimes the story says enough on its own.</p>`}</div></section></div>` });
}

async function readForm(req) {
  if (!req.headers['content-type']?.startsWith('application/x-www-form-urlencoded')) throw Object.assign(new Error('Expected form data'), { status: 415 });
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > MAX_BODY) throw Object.assign(new Error('Form is too large'), { status: 413 });
  }
  return Object.fromEntries(new URLSearchParams(body));
}

export function createApp() {
  return createServer(async (req, res) => {
    try {
      const path = new URL(req.url, 'http://localhost').pathname;
      if (req.method === 'GET' && path === '/styles.css') {
        return send(res, 200, await readFile(CSS_FILE, 'utf8'), 'text/css; charset=utf-8');
      }
      if (req.method === 'GET' && path === '/') return send(res, 200, home(await loadBooks()));
      if (req.method === 'GET' && path === '/books/new') return send(res, 200, formPage());
      if (req.method === 'POST' && path === '/books') {
        const values = await readForm(req);
        const title = (values.title || '').trim();
        const author = (values.author || '').trim();
        const notes = (values.notes || '').trim();
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
          return send(res, 400, formPage(values, 'Please enter a title and author within the allowed lengths.'));
        }
        const id = randomUUID();
        await updateBooks((books) => books.unshift({ id, title, author, notes, status: 'reading', createdAt: new Date().toISOString() }));
        return redirect(res, `/books/${id}`);
      }
      const finish = path.match(/^\/books\/([0-9a-f-]+)\/finish$/);
      if (req.method === 'POST' && finish) {
        const found = await updateBooks((books) => {
          const book = books.find((item) => item.id === finish[1]);
          if (!book) return false;
          book.status = 'finished';
          return true;
        });
        return found ? redirect(res, `/books/${finish[1]}`) : send(res, 404, errorPage('Book not found'));
      }
      const match = path.match(/^\/books\/([0-9a-f-]+)$/);
      if (req.method === 'GET' && match) {
        const book = (await loadBooks()).find((item) => item.id === match[1]);
        return book ? send(res, 200, detail(book)) : send(res, 404, errorPage('Book not found'));
      }
      return send(res, 404, errorPage('Page not found'));
    } catch (error) {
      console.error(error);
      return send(res, error.status || 500, errorPage(error.status ? error.message : 'Something went wrong'));
    }
  });
}

function errorPage(message) {
  return layout({ title: message, content: `<div class="error-page"><span class="error-symbol">✳</span><h1>${escapeHtml(message)}.</h1><p>Let’s get you back to your books.</p><a class="button primary" href="/">Back to library ${icon('arrow', 18)}</a></div>` });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === fileURLToPath(new URL(`file://${process.argv[1]}`))) {
  const port = Number(process.env.PORT || 3000);
  createApp().listen(port, () => console.log(`Marginalia is ready at http://localhost:${port}`));
}

