import { test, expect } from 'vitest';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function listen(app) {
  await new Promise((resolve) => app.listen(0, '127.0.0.1', resolve));
  return `http://127.0.0.1:${app.address().port}`;
}

async function close(app) {
  await new Promise((resolve) => app.close(resolve));
}

test('books can be added, viewed by link, finished, and loaded after restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'marginalia-'));
  process.env.DATA_FILE = join(directory, 'books.json');
  const { createApp } = await import('./server.js');
  let app = createApp();
  try {
    let url = await listen(app);
    let response = await fetch(url);
    expect(response.status).toBe(200);
    expect(await response.text()).toContain('Currently reading');

    response = await fetch(`${url}/books`, {
      method: 'POST', redirect: 'manual',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ title: 'The <Book>', author: 'A & B', notes: 'A note\nwith a second line' }),
    });
    expect(response.status).toBe(303);
    const path = response.headers.get('location');
    expect(path).toMatch(/^\/books\/[0-9a-f-]+$/);
    response = await fetch(url + path);
    expect(response.status).toBe(200);
    const detail = await response.text();
    expect(detail).toContain('The &lt;Book&gt;');
    expect(detail).toContain('A &amp; B');
    expect(detail).toContain('A note\nwith a second line');
    expect(detail).toContain('Mark as finished');

    response = await fetch(url);
    expect(await response.text()).toContain('The &lt;Book&gt;');
    response = await fetch(`${url}${path}/finish`, { method: 'POST', redirect: 'manual' });
    expect(response.status).toBe(303);
    expect(JSON.parse(await readFile(process.env.DATA_FILE, 'utf8'))[0].status).toBe('finished');
    await close(app);
    app = createApp();
    url = await listen(app);
    response = await fetch(url + path);
    expect(await response.text()).toContain('A story completed');
    response = await fetch(url);
    const home = await response.text();
    expect(home).toContain('Finished books');
    expect(home).toContain('The &lt;Book&gt;');
    expect((await fetch(`${url}/books/not-a-real-id`)).status).toBe(404);
  } finally {
    if (app.listening) await close(app);
    await rm(directory, { recursive: true, force: true });
  }
});

test('form rejects missing required details', async () => {
  const { createApp } = await import('./server.js');
  const app = createApp();
  try {
    const url = await listen(app);
    const response = await fetch(`${url}/books`, {
      method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ title: 'Just a title' }),
    });
    expect(response.status).toBe(400);
    expect(await response.text()).toContain('Please enter a title and author');
  } finally {
    await close(app);
  }
});

