    expect(await response.text()).toContain('The &lt;Book&gt;');
    response = await fetch(`${url}${path}/finish`, { method: 'POST', redirect: 'manual' });
    expect(response.status).toBe(303);
    expect(JSON.parse(await readFile(process.env.DATA_FILE, 'utf8'))[0].status).toBe('finished');
    await close(app);
    app = createApp();
    url = await listen(app);
    response = await fetch(url + path);
    expect(await response.text()).toContain('A story completed');
    response = await fetch(url);
    const home = await response.text();
    expect(home).toContain('Finished books');
    expect(home).toContain('The &lt;Book&gt;');
    expect((await fetch(`${url}/books/not-a-real-id`)).status).toBe(404);
  } finally {
    if (app.listening) await close(app);
    await rm(directory, { recursive: true, force: true });
  }
});

